import { getDb } from './utils/db.js';
import type { VercelRequest, VercelResponse } from '@vercel/node';

export default async function handler(req: VercelRequest, res: VercelResponse) {
    const db = getDb();
    
    const services = [
        { title: "Limpieza Facial Profunda", price: "45", duration: "60 min", description: "Extracción, exfoliación enzimática y mascarilla revitalizante.", image_url: "data:image/jpg;base64," },
        { title: "Ácido Hialurónico", price: "280", duration: "45 min", description: "Relleno dérmico premium para labios, pómulos y surcos.", image_url: "data:image/jpg;base64," },
        { title: "Botox Preventivo", price: "220", duration: "30 min", description: "Toxina botulínica para líneas de expresión y frente.", image_url: "data:image/jpg;base64," },
        { title: "Peeling Químico", price: "95", duration: "45 min", description: "Renovación celular con ácidos glicólico y mandélico.", image_url: "data:image/jpg;base64," },
        { title: "Microblading Cejas", price: "180", duration: "90 min", description: "Diseño hiperrealista pelo a pelo con pigmentos premium.", image_url: "data:image/jpg;base64," },
        { title: "Masaje Relajante", price: "55", duration: "60 min", description: "Masaje descontracturante con aromaterapia y piedras calientes.", image_url: "data:image/jpg;base64," },
    ];

    try {
        await db.query("DELETE FROM services");
        for (const s of services) {
            await db.query(
                "INSERT INTO services (title, price, duration, description, image_url, active) VALUES ($1, $2, $3, $4, $5, true)",
                [s.title, s.price, s.duration, s.description, s.image_url]
            );
        }
        return res.status(200).json({ success: true, message: "Seed complete with Base64 images" });
    } catch (e: any) {
        return res.status(500).json({ error: e.message });
    }
}
